import{_ as i,a0 as p,w as s,s as d,I as e,x as t,a1 as r,A as n,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"如何為Linux系統中的SSH添加雙重認證 | LCTT x X-CMD","titleTemplate":false,"description":"如何為Linux系統中的SSH添加雙重認證 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何為Linux系統中的SSH添加雙重認證 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何為Linux系統中的SSH添加雙重認證 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140709 How to set up two-factor authentication for SSH login on Linux","title":"如何為Linux系統中的SSH添加雙重認證","tag":"201408","desc":""},"relativePath":"201408/20140709 How to set up two-factor authentication for SSH login on Linux.md","filePath":"[post].md"}'),u={name:"201408/20140709 How to set up two-factor authentication for SSH login on Linux.md"};function g(m,o,h,c,f,x){const a=p("Link");return s(),d("div",null,[o[29]||(o[29]=e("h1",{id:"如何為linux系統中的ssh添加雙重認證",tabindex:"-1"},[t("如何為Linux系統中的SSH添加雙重認證 "),e("a",{class:"header-anchor",href:"#如何為linux系統中的ssh添加雙重認證","aria-label":"Permalink to “如何為Linux系統中的SSH添加雙重認證”"},"​")],-1)),o[30]||(o[30]=e("p",null,"近來很多知名企業都出現了密碼泄露，業內對多重認證的呼聲也越來越高。在這種多重認證的系統中，用户需要通過兩種不同的認證程序：提供他們知道的信息（如 用户名/密碼），再借助其他工具提供用户所不知道的信息（如 用手機生成的一次性密碼）。這種組合方式常叫做雙因子認證或者兩階段驗證。",-1)),e("p",null,[o[3]||(o[3]=t("為了鼓勵廣泛採用雙因子認證的方式，Google公司發佈了",-1)),r(a,{href:"http://code.google.com/p/google-authenticator/"},{default:n(()=>[...o[0]||(o[0]=[t("Google Authenticator",-1)])]),_:1}),o[4]||(o[4]=t("，一款開源的，可基於開放規則（如 HMAP/基於時間）生成一次性密碼的軟件。這是一款跨平台軟件，可運行在Linux, ",-1)),r(a,{href:"https://play.google.com/store/apps/details?id=com.google.android.apps.authenticator2"},{default:n(()=>[...o[1]||(o[1]=[t("Android",-1)])]),_:1}),o[5]||(o[5]=t(", ",-1)),r(a,{href:"https://itunes.apple.com/us/app/google-authenticator/id388497605"},{default:n(()=>[...o[2]||(o[2]=[t("iOS",-1)])]),_:1}),o[6]||(o[6]=t("。Google公司同時也支持插件式鑑別模組PAM(pluggable authentication module)，使其能和其他也適用PAM進行驗證的工具（如OpenSSH）協同工作。",-1))]),e("p",null,[o[8]||(o[8]=t("在本教程中，我們將敍述集成OpenSSH和Google提供的認證器實現",-1)),o[9]||(o[9]=e("strong",null,"如何為SSH服務設置雙因子認證",-1)),o[10]||(o[10]=t("。我將使用一款",-1)),r(a,{href:"http://xmodulo.com/go/android_guide"},{default:n(()=>[...o[7]||(o[7]=[t("Android",-1)])]),_:1}),o[11]||(o[11]=t("設備來生成一次性密碼，本教程中需要兩樣武器：(1)一台運行着OpenSSH服務的Linux終端，(2)一台安卓設備。",-1))]),o[31]||(o[31]=l(`<h3 id="在linux系統中安裝google-authenticator" tabindex="-1">在Linux系統中安裝Google Authenticator <a class="header-anchor" href="#在linux系統中安裝google-authenticator" aria-label="Permalink to “在Linux系統中安裝Google Authenticator”">​</a></h3><p>第一步需要在運行着OpenSSH服務的Linux主機上安裝Google認證器。按照如下步驟安裝Google認證器及其PAM模組。</p><h4 id="用安裝包安裝-google-authenticator" tabindex="-1">用安裝包安裝 Google Authenticator <a class="header-anchor" href="#用安裝包安裝-google-authenticator" aria-label="Permalink to “用安裝包安裝 Google Authenticator”">​</a></h4><p>如果你不想自己構建 Google Authenticator，在幾個 Linux 發行版上有已經編譯好的安裝包。安裝包裏面包含 Google Authenticator 二進制程序和 PAM 模組。</p><p>在 Ubuntu 上安裝 Google Authenticator：</p><pre><code>$ sudo apt-get install libpam-google-authenticator
</code></pre><p>在 Fedora 上安裝 Google Authenticator：</p><pre><code>$ sudo yum install google-authenticator
</code></pre><p>在 CentOS 上安裝 Google Authenticator ，需要首先啓用 EPEL 軟件庫，然後運行如下命令：</p><pre><code>$ sudo yum install google-authenticator
</code></pre><p>如果不想使用已經編譯好的安裝包，或者你的 Linux 發行版不在此列，可以自行編譯：</p><h4 id="在-linux-上-google-authenticator" tabindex="-1">在 Linux 上 Google Authenticator <a class="header-anchor" href="#在-linux-上-google-authenticator" aria-label="Permalink to “在 Linux 上 Google Authenticator”">​</a></h4><p>首先，安裝構建 Google Authenticator 所需的軟件包。</p><p>在 Debian、 Ubuntu 或 Linux Mint 上：</p><pre><code>$ sudo apt-get install wget make gcc libpam0g-dev
</code></pre><p>在 CentOS、 Fedora 或 RHEL上：</p><pre><code>$ sudo yum install wget make gcc pam-devel
</code></pre><p>然後下載 Google Authenticator 的源代碼，並按如下命令編譯。</p><pre><code>$ wget https://google-authenticator.googlecode.com/files/libpam-google-authenticator-1.0-source.tar.bz2
$ tar xvfvj libpam-google-authenticator-1.0-source.tar.bz2
$ cd libpam-google-authenticator-1.0
$ make
</code></pre><p>如果構建成功，你會在目錄中看到 pam_google_authenticator.so 和 google-authenticator 兩個文件。</p><p>最後，將 Google Authenticator 安裝到合適位置</p><pre><code>$ sudo make install
</code></pre><h4 id="排錯" tabindex="-1">排錯 <a class="header-anchor" href="#排錯" aria-label="Permalink to “排錯”">​</a></h4><p>當編譯 Google Authenticator 時出現如下錯誤：</p><pre><code>fatal error: security/pam_appl.h: No such file or directory
</code></pre><p>要修復這個問題，請安裝如下依賴包。</p><p>在 Debian、 Ubuntu 或 Linux Mint 上：</p><pre><code>$ sudo apt-get install libpam0g-dev
</code></pre><p>在 CentOS、 Fedora 或 RHEL 上：</p><pre><code>$ sudo yum install pam-devel
</code></pre><p>當Google認證器安裝好後，你需要在Linux主機上創建驗證密鑰，並且在安卓設備上註冊，注意這項配置操作是一次性的。我們將詳細敍述如何完成這些操作：</p><h3 id="生成驗證密鑰" tabindex="-1">生成驗證密鑰 <a class="header-anchor" href="#生成驗證密鑰" aria-label="Permalink to “生成驗證密鑰”">​</a></h3><p>在Linux主機上運行Google認證器</p><pre><code>$ google-authenticator 
</code></pre><p>你將看到一個QR碼，它使用如下圖形表示我們數字形態的密鑰。一會我們要用到它在安卓設備上完成配置。</p><p><img src="https://farm4.staticflickr.com/3843/14573264401_d3f5a2f247_z.jpg" alt=""><img src="https://farm4.staticflickr.com/3848/14390010599_18dfc23d76_z.jpg" alt=""></p><p>Google認證器會問一些問題，如果你不確定，就回答&quot;Yes&quot;。這個應急備用驗證碼(圖中 emergency scratch codes）可以在你由於丟失了綁定的安卓設備的情況下（所以不能得到生成的一次性密碼）恢復訪問。最好將應急備用驗證碼妥善保存。</p><h3 id="在安卓設備上運行google認證器" tabindex="-1">在安卓設備上運行Google認證器 <a class="header-anchor" href="#在安卓設備上運行google認證器" aria-label="Permalink to “在安卓設備上運行Google認證器”">​</a></h3>`,38)),e("p",null,[o[13]||(o[13]=t("我們需要在安卓設備上安裝",-1)),r(a,{href:"https://play.google.com/store/apps/details?id=com.google.android.apps.authenticator2"},{default:n(()=>[...o[12]||(o[12]=[t("Google Authenticator app",-1)])]),_:1}),o[14]||(o[14]=t("才能完成雙因子認證，到Google Play下載並安裝一個。在安卓設備上運行Google認證器，找到下圖所示中的配置菜單。",-1))]),o[32]||(o[32]=e("p",null,[e("img",{src:"https://farm6.staticflickr.com/5574/14554094476_bfc070d242_z.jpg",alt:""})],-1)),e("p",null,[o[16]||(o[16]=t('你可以選擇"Scan a barcode" 或者"Enter provided key"選項。"Scan a barcode"允許你掃描QR碼來完成密鑰的輸入，在此可能需要先安裝掃描軟件',-1)),r(a,{href:"https://play.google.com/store/apps/details?id=com.google.zxing.client.android"},{default:n(()=>[...o[15]||(o[15]=[t("Barcode Scanner app",-1)])]),_:1}),o[17]||(o[17]=t('。如果選擇"Enter provided key"選項，你可以使用鍵盤輸入驗證密鑰，如下圖所示：',-1))]),o[33]||(o[33]=l(`<p><img src="https://farm6.staticflickr.com/5535/14596723603_d510dbe48d_z.jpg" alt=""></p><p>無論採用上述兩種選項的任何方式，一旦成功，你將看到註冊成功提示和一次性密碼，如下圖所示：</p><p><img src="https://farm6.staticflickr.com/5586/14390009579_5ba109bf5b_z.jpg" alt=""></p><h3 id="為ssh服務器用google認證器" tabindex="-1">為SSH服務器用Google認證器 <a class="header-anchor" href="#為ssh服務器用google認證器" aria-label="Permalink to “為SSH服務器用Google認證器”">​</a></h3><p>最終我們需要修改兩個文件來完成集成Google認證器和OpenSSH服務這臨門一腳。</p><p>首先，修改PAM配置文件，命令和需添加的內容如下：</p><pre><code>$ sudo vi /etc/pam.d/sshd 
</code></pre><hr><pre><code>auth required pam_google_authenticator.so
</code></pre><p>然後打開SSH配置文件，找到參數ChallengeResponseAuthentication，並啓用它。</p><pre><code>$ sudo vi /etc/ssh/sshd_config 
</code></pre><hr><p>ChallengeResponseAuthentication yes</p><p>最後，重啓SSH服務。</p><p>在 Ubuntu、 Debian 和 Linux Mint 上：</p><pre><code>$ sudo service ssh restart 
</code></pre><p>在Fedora （或 CentOS/RHEL 7）上：</p><pre><code>$ sudo systemctl restart sshd 
</code></pre><p>在CentOS 6.x或 RHEL 6.x上：</p><pre><code>$ sudo service sshd restart 
</code></pre><h3 id="驗證雙因子認證" tabindex="-1">驗證雙因子認證 <a class="header-anchor" href="#驗證雙因子認證" aria-label="Permalink to “驗證雙因子認證”">​</a></h3><p>在綁定的安卓設備上運行Google認證器，獲得一個一次性驗證碼，該驗證碼30秒內有效，一旦過期，將重新生成一個新的驗證碼。</p><p><img src="https://farm3.staticflickr.com/2937/14389989618_d9355dcbb2_z.jpg" alt=""></p><p>現在和往常一樣，使用SSH登錄終端</p><pre><code>$ ssh user@ssh_server 
</code></pre><p>當提示你輸入驗證碼的時候，輸入我們剛獲得的驗證碼。驗證成功後，再輸入SSH的登錄密碼。</p><p><img src="https://farm3.staticflickr.com/2938/14389952480_93351f12a4_z.jpg" alt=""></p><p>雙因子認證通過在用户密碼前新增一層來有效的保護我們脆弱的用户密碼。你可以使用Google認證器來保護我們其他的密碼，如Google賬户, WordPress.com, Dropbox.com, Outlook.com等等。是否使用這項技術，取決於我們自己，但採用雙因子認證已經是行業的大趨勢了。</p><hr>`,29)),e("p",null,[o[19]||(o[19]=t("via: ",-1)),r(a,{href:"http://xmodulo.com/2014/07/two-factor-authentication-ssh-login-linux.html"},{default:n(()=>[...o[18]||(o[18]=[t("http://xmodulo.com/2014/07/two-factor-authentication-ssh-login-linux.html",-1)])]),_:1})]),e("p",null,[o[22]||(o[22]=t("譯者：",-1)),r(a,{href:"https://github.com/nd0104"},{default:n(()=>[...o[20]||(o[20]=[t("nd0104",-1)])]),_:1}),o[23]||(o[23]=t(" 校對：",-1)),r(a,{href:"https://github.com/wxy"},{default:n(()=>[...o[21]||(o[21]=[t("wxy",-1)])]),_:1})]),e("p",null,[o[26]||(o[26]=t("本文由 ",-1)),r(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...o[24]||(o[24]=[t("LCTT",-1)])]),_:1}),o[27]||(o[27]=t(" 原創翻譯，",-1)),r(a,{href:"http://linux.cn/"},{default:n(()=>[...o[25]||(o[25]=[t("Linux中國",-1)])]),_:1}),o[28]||(o[28]=t(" 榮譽推出",-1))])])}const G=i(u,[["render",g]]);export{L as __pageData,G as default};
